def transform(grid):
    # Isolated T tetriminoes are categorized by the direction of their single-cell stem.
    h,w=len(grid),len(grid[0]); seen=set(); obs=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=2 or (r,c) in seen: continue
        st=[(r,c)]; seen.add((r,c)); cells=[]
        while st:
          y,x=st.pop(); cells.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            q=(y+dy,x+dx)
            if 0<=q[0]<h and 0<=q[1]<w and grid[q[0]][q[1]]==2 and q not in seen: seen.add(q); st.append(q)
        if len(cells)==4:
          rr=[y for y,x in cells]; cc=[x for y,x in cells]
          rc={y:rr.count(y) for y in set(rr)}; ccnt={x:cc.count(x) for x in set(cc)}
          if max(rc.values())==3:
            bar=max(rc,key=rc.get); stem=next(y for y,n in rc.items() if n==1); direction='up' if stem<bar else 'down'
          else:
            bar=max(ccnt,key=ccnt.get); stem=next(x for x,n in ccnt.items() if n==1); direction='left' if stem<bar else 'right'
          obs.append((min(y for y,x in cells),min(x for y,x in cells),direction))
    out=[[0]*6 for _ in range(3)]
    # Each direction has fixed symbol slot, with repeated instances placed vertically.
    for _,_,d in obs:
      if d=='up': out[0][0]=3
      elif d=='down':
        if out[0][3]==0: out[0][3]=1
        else: out[2][3]=1
      elif d=='left': out[0][2]=3
      elif d=='right': out[0][5]=1
    return out
